<script setup>
import { computed, onMounted, onBeforeUnmount, ref, nextTick } from 'vue';

const props = defineProps({ mode: { type: String, default: 'index' }, indexUrl: String, salesUrl: String, booksUrl: String });
const data = ref(null); const loading = ref(false); const error = ref(''); const startDate = ref(''); const endDate = ref('');
let chart;
const endpoint = computed(() => ({ index: props.indexUrl, sales: props.salesUrl, books: props.booksUrl }[props.mode]));
const money = value => '$' + Number(value || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const number = value => Number(value || 0).toLocaleString();
function drawChart() {
    if (props.mode !== 'index' || !window.Chart || !data.value) return;
    const canvas = document.getElementById('salesChart'); if (!canvas) return;
    chart?.destroy(); chart = new window.Chart(canvas, { type: 'line', data: { labels: data.value.salesByDay.map(row => row.date), datasets: [{ label: 'Revenue', data: data.value.salesByDay.map(row => Number(row.revenue)), tension: .4, fill: true }] }, options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } } });
}
async function load(url = window.location.href, history = false) {
    loading.value = true; error.value = '';
    try {
        const response = await fetch(url, { headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' });
        if (!response.ok) throw new Error('Unable to load report data.');
        data.value = await response.json(); startDate.value = data.value.startDate || ''; endDate.value = data.value.endDate || '';
        if (history) window.history.pushState({}, '', url);
        await nextTick(); drawChart();
    } catch (e) { error.value = e.message || 'Unable to load report data.'; }
    finally { loading.value = false; }
}
function apply() { const url = new URL(endpoint.value, window.location.origin); if (startDate.value) url.searchParams.set('start_date', startDate.value); if (endDate.value) url.searchParams.set('end_date', endDate.value); load(url, true); }
function reset() { load(endpoint.value, true); }
function pageUrl(page) { const url = new URL(endpoint.value, window.location.origin); if (startDate.value) url.searchParams.set('start_date', startDate.value); if (endDate.value) url.searchParams.set('end_date', endDate.value); url.searchParams.set('page', page); return url; }
function onPop() { load(window.location.href); }
onMounted(() => { window.addEventListener('popstate', onPop); load(); }); onBeforeUnmount(() => { window.removeEventListener('popstate', onPop); chart?.destroy(); });
</script>

<template>
<div :class="['dashboard-section','reports-page', mode === 'books' ? 'books-report-page' : '', loading ? 'is-loading' : '']" :aria-busy="loading">
  <div class="dashboard-panel reports-header-panel"><div class="reports-header-content"><div><h5>{{ mode === 'index' ? 'Reports Dashboard' : mode === 'sales' ? 'Sales Report' : 'Books Report' }}</h5><p>{{ mode === 'index' ? 'Monitor sales, orders, customers and inventory' : mode === 'sales' ? 'Analyze delivered orders and revenue performance' : 'Monitor books, inventory and sales performance.' }}</p></div><div class="reports-header-actions"><a v-if="mode === 'index'" :href="salesUrl" class="reports-back-btn"><i class="bi bi-graph-up"></i> Sales Report</a><a v-else :href="indexUrl" class="reports-back-btn"><i class="bi bi-arrow-left"></i> Reports Dashboard</a></div></div></div>
  <div class="dashboard-panel reports-filter-panel"><form class="reports-filter-form" @submit.prevent="apply"><div class="reports-filter-row"><div class="reports-filter-group"><label for="start_date">Start Date</label><input id="start_date" v-model="startDate" type="date"></div><div class="reports-filter-group"><label for="end_date">End Date</label><input id="end_date" v-model="endDate" type="date"></div><div class="reports-filter-actions"><button class="reports-filter-btn" type="submit"><i class="bi bi-funnel"></i> Apply</button><button class="reports-reset-btn" type="button" @click="reset"><i class="bi bi-arrow-counterclockwise"></i> Reset</button></div></div></form></div>
  <div v-if="error" class="alert alert-danger" role="alert">{{ error }} <button class="btn btn-sm btn-outline-danger ms-2" @click="load()">Retry</button></div>
  <div v-if="loading && !data" class="reports-table-empty">Loading report…</div>
  <template v-if="data">
    <template v-if="mode === 'index'">
      <div class="reports-stats-grid"><div v-for="s in [{label:'Total Revenue',value:money(data.totalRevenue),icon:'bi-currency-dollar',tone:'revenue'},{label:'Total Orders',value:number(data.totalOrders),icon:'bi-bag-check',tone:'orders'},{label:'Books Sold',value:number(data.booksSold),icon:'bi-book',tone:'books'},{label:'New Customers',value:number(data.totalCustomers),icon:'bi-people',tone:'users'}]" :key="s.label" class="reports-stat-card"><div :class="['reports-stat-icon','reports-icon-'+s.tone]"><i :class="['bi',s.icon]"></i></div><div class="reports-stat-content"><span>{{ s.label }}</span><strong>{{ s.value }}</strong></div></div></div>
      <div class="reports-stats-grid"><div v-for="s in [{label:'Pending Orders',value:number(data.pendingOrders),icon:'bi-hourglass-split',tone:'warning'},{label:'Delivered Orders',value:number(data.deliveredOrders),icon:'bi-check-circle',tone:'success'},{label:'Cancelled Orders',value:number(data.cancelledOrders),icon:'bi-x-circle',tone:'danger'},{label:'Average Order',value:money(data.averageOrderValue),icon:'bi-calculator',tone:'books'}]" :key="s.label" class="reports-stat-card"><div :class="['reports-stat-icon','reports-icon-'+s.tone]"><i :class="['bi',s.icon]"></i></div><div class="reports-stat-content"><span>{{ s.label }}</span><strong>{{ s.value }}</strong></div></div></div>
      <div class="dashboard-panel reports-panel"><div class="reports-panel-header"><div><h5>Sales Overview</h5><p>Delivered revenue during the selected period</p></div></div><div class="reports-chart-wrapper"><canvas id="salesChart"></canvas></div></div>
      <div class="reports-two-column"><div class="dashboard-panel reports-panel"><div class="reports-panel-header"><div><h5>Top Selling Books</h5><p>Best performing books</p></div><a :href="booksUrl" class="reports-back-btn">View All</a></div><div class="reports-list"><div v-for="book in data.topBooks" :key="book.title" class="reports-list-item"><div class="reports-list-info"><strong>{{ book.title }}</strong><span>{{ number(book.total_sold) }} books sold</span></div><strong>{{ money(book.revenue) }}</strong></div><div v-if="!data.topBooks.length" class="reports-table-empty">No sales data available.</div></div></div><div class="dashboard-panel reports-panel"><div class="reports-panel-header"><div><h5>Low Stock</h5><p>Books that need attention</p></div><a :href="booksUrl" class="reports-back-btn">View All</a></div><div class="reports-list"><div v-for="book in data.lowStockBooks" :key="book.title" class="reports-list-item"><div class="reports-list-info"><strong>{{ book.title }}</strong><span>Stock: {{ book.stock }}</span></div><span :class="['reports-stock-badge',book.stock <= 0 ? 'reports-stock-danger':'reports-stock-warning']">{{ book.stock <= 0 ? 'Out of stock':'Low stock' }}</span></div><div v-if="!data.lowStockBooks.length" class="reports-table-empty">No low stock books.</div></div></div></div>
      <div class="dashboard-panel reports-panel reports-orders-panel"><div class="reports-panel-header"><div><h5>Recent Orders</h5><p>Latest orders during the selected period</p></div><a :href="salesUrl" class="reports-back-btn">View Sales</a></div><div class="reports-table-wrapper"><table class="reports-table"><thead><tr><th>Order</th><th>Customer</th><th>Book</th><th>Status</th><th>Total</th><th>Date</th></tr></thead><tbody><tr v-for="(row,i) in data.recentOrders" :key="row.order_number || i"><td><span class="reports-order-number">{{ row.order_number }}</span></td><td>{{ row.customer }}</td><td><span class="reports-book-name">{{ row.book }}</span></td><td><span :class="['reports-stock-badge',row.status === 'cancelled'?'reports-stock-danger':row.status === 'pending'?'reports-stock-warning':'reports-stock-normal']">{{ row.status }}</span></td><td><strong>{{ money(row.total_price) }}</strong></td><td>{{ row.date }}</td></tr><tr v-if="!data.recentOrders.length"><td colspan="6"><div class="reports-table-empty">No recent orders.</div></td></tr></tbody></table></div></div>
    </template>
    <template v-else-if="mode === 'sales'"><div class="reports-stats-grid"><div v-for="s in [{label:'Orders',value:number(data.totalOrders),tone:'orders'},{label:'Revenue',value:money(data.totalRevenue),tone:'revenue'},{label:'Books Sold',value:number(data.booksSold),tone:'books'},{label:'Average Order',value:money(data.averageOrderValue),tone:'users'}]" :key="s.label" class="reports-stat-card"><div :class="['reports-stat-icon','reports-icon-'+s.tone]"><i class="bi bi-graph-up"></i></div><div class="reports-stat-content"><span>{{ s.label }}</span><strong>{{ s.value }}</strong></div></div></div><div class="dashboard-panel reports-panel reports-orders-panel"><div class="reports-panel-header"><div><h5>Sales</h5><p>Delivered orders during the selected period</p></div></div><div class="reports-table-wrapper"><table class="reports-table"><thead><tr><th>Order</th><th>Customer</th><th>Book</th><th>Quantity</th><th>Total</th><th>Payment</th><th>Date</th></tr></thead><tbody><tr v-for="(row,i) in data.orders" :key="row.order_number || i"><td><span class="reports-order-number">{{ row.order_number }}</span></td><td>{{ row.customer }}</td><td><span class="reports-book-name">{{ row.book }}</span></td><td>{{ row.quantity }}</td><td><strong>{{ money(row.total_price) }}</strong></td><td>{{ (row.payment_method || 'N/A').replaceAll('_',' ') }}</td><td>{{ row.date }}</td></tr><tr v-if="!data.orders.length"><td colspan="7"><div class="reports-table-empty">No sales found for this period.</div></td></tr></tbody></table></div><div v-if="data.pagination.last_page > 1" class="reports-pagination"><button class="btn btn-sm btn-light" :disabled="data.pagination.current_page<=1" @click="load(pageUrl(data.pagination.current_page-1),true)">Previous</button><span>{{ data.pagination.current_page }} / {{ data.pagination.last_page }}</span><button class="btn btn-sm btn-light" :disabled="data.pagination.current_page>=data.pagination.last_page" @click="load(pageUrl(data.pagination.current_page+1),true)">Next</button></div></div></template>
    <template v-else><div class="reports-stats-grid"><div v-for="s in [{label:'Total Books',value:number(data.totalBooks),tone:'books'},{label:'Active Books',value:number(data.activeBooks),tone:'success'},{label:'Low Stock',value:number(data.lowStock),tone:'warning'},{label:'Out of Stock',value:number(data.outOfStock),tone:'danger'},{label:'Books Sold',value:number(data.totalSold),tone:'orders'},{label:'Total Revenue',value:money(data.totalRevenue),tone:'revenue'}]" :key="s.label" class="reports-stat-card"><div :class="['reports-stat-icon','reports-icon-'+s.tone]"><i class="bi bi-book"></i></div><div class="reports-stat-content"><span>{{ s.label }}</span><strong>{{ s.value }}</strong></div></div></div><div class="dashboard-panel reports-panel books-report-panel"><div class="reports-panel-header"><div><h5>All Books</h5><p>Book inventory and sales performance for the selected period.</p></div></div><div class="reports-table-wrapper books-report-table-wrapper"><table class="reports-table books-report-table"><thead><tr><th>Book</th><th>Category</th><th>Seller</th><th>Price</th><th>Stock</th><th>Sold</th><th>Revenue</th><th>Status</th></tr></thead><tbody><tr v-for="(book,i) in data.books" :key="book.title+i"><td><div class="books-report-book-cell"><div class="books-report-cover"><img v-if="book.cover" :src="book.cover" :alt="book.title"><div v-else class="books-report-cover-placeholder"><i class="bi bi-book"></i></div></div><div class="books-report-book-info"><strong>{{ book.title }}</strong><span>{{ book.isbn || 'No ISBN' }}</span></div></div></td><td><span class="books-report-secondary-text">{{ book.category }}</span></td><td><span class="books-report-secondary-text">{{ book.seller }}</span></td><td><strong class="books-report-price">{{ money(book.price) }}</strong></td><td><span :class="['reports-stock-badge',book.stock<=0?'reports-stock-danger':book.stock<=5?'reports-stock-warning':'reports-stock-normal']">{{ book.stock<=0?'Out of stock':book.stock<=5?`${number(book.stock)} left`:number(book.stock) }}</span></td><td><strong class="books-report-sold">{{ number(book.sold_count) }}</strong></td><td><strong class="books-report-revenue">{{ money(book.revenue) }}</strong></td><td><span :class="['reports-stock-badge',book.status==='approved'?'reports-stock-normal':book.status==='pending'?'reports-stock-warning':'reports-stock-danger']">{{ book.status }}</span></td></tr><tr v-if="!data.books.length"><td colspan="8"><div class="reports-table-empty">No books found.</div></td></tr></tbody></table></div><div v-if="data.pagination.last_page>1" class="reports-pagination"><button class="btn btn-sm btn-light" :disabled="data.pagination.current_page<=1" @click="load(pageUrl(data.pagination.current_page-1),true)">Previous</button><span>{{ data.pagination.current_page }} / {{ data.pagination.last_page }}</span><button class="btn btn-sm btn-light" :disabled="data.pagination.current_page>=data.pagination.last_page" @click="load(pageUrl(data.pagination.current_page+1),true)">Next</button></div></div></template>
  </template>
</div>
</template>
